                    return obj[n]
        d = None
        try:
            d = obj.__dict__
        except Exception:
            d = None
        if is_dict(d):
            for n in names:
                if n in d:
                    return d[n]
        return default

    depot = get_value(instance, ("depot", "depot_id"), 0)
    capacity = get_value(instance, ("capacity", "vehicle_capacity"), None)
    demands_in = get_value(instance, ("demands", "demand"), {})
    coords = get_value(instance, ("coordinates", "coords", "positions", "locations"), None)
    dist_matrix = get_value(instance, ("distance_matrix", "distances", "matrix"), None)
    customers = get_value(instance, ("customers", "customer_ids"), None)

    if customers is None:
        if is_dict(demands_in):
            customers = [k for k in demands_in.keys() if k != depot]
        elif coords is not None:
            customers = [i for i in range(len(coords)) if i != depot]
        elif dist_matrix is not None:
            customers = [i for i in range(len(dist_matrix)) if i != depot]
        else:
            customers = []
    customers = list(customers)

    if is_dict(demands_in):
        demands = demands_in
    else:
        demands = {}
        if demands_in is not None:
            for i in range(len(demands_in)):
                demands[i] = demands_in[i]

    def demand(c):
        return demands.get(c, 0)

    def dist(a, b):
        if dist_matrix is not None:
            return dist_matrix[a][b]
        if coords is not None:
            ax, ay = coords[a]
            bx, by = coords[b]
            dx = ax - bx
            dy = ay - by
            return (dx * dx + dy * dy) ** 0.5
        return 0

    if capacity is None:
        capacity = sum(demand(c) for c in customers)

    if coords is not None and depot < len(coords):
        dx0, dy0 = coords[depot]

        def key(c):
            x, y = coords[c]
            vx = x - dx0
            vy = y - dy0
            half = 0 if (vy > 0 or (vy == 0 and vx >= 0)) else 1
            slope = abs(vy) / (abs(vx) + abs(vy) + 1e-12)
            return (half, slope, dist(depot, c), c)

        customers.sort(key=key)
    else:
        customers.sort(key=lambda c: (demand(c), c))

    unrouted = customers[:]
    routes = []

    def route_load(route):
        s = 0
        for c in route:
            s += demand(c)
        return s

    def route_cost(route):
        if not route:
            return 0
        total = dist(depot, route[0])
        for i in range(len(route) - 1):
            total += dist(route[i], route[i + 1])
        total += dist(route[-1], depot)
        return total

    def insertion_delta(route, pos, c):
        prev = depot if pos == 0 else route[pos - 1]
        nxt = depot if pos == len(route) else route[pos]
        return dist(prev, c) + dist(c, nxt) - dist(prev, nxt)

    def best_insertion(route, c):
        best_pos = 0
        best_delta = None
        for pos in range(len(route) + 1):
            d = insertion_delta(route, pos, c)
            if best_delta is None or d < best_delta - 1e-12 or (abs(d - best_delta) <= 1e-12 and pos < best_pos):
                best_delta = d
                best_pos = pos
        return best_pos, best_delta

    while unrouted:
        feasible = [c for c in unrouted if demand(c) <= capacity]
        if not feasible:
            feasible = unrouted[:]
        seed = min(feasible, key=lambda c: (dist(depot, c), demand(c), c))
        route = [seed]
        unrouted.remove(seed)
        load = demand(seed)

        improved = True
        while improved and unrouted:
            improved = False
            best_c = None
            best_pos = None
            best_score = None
            for c in unrouted:
                d = demand(c)
                if load + d > capacity:
                    continue
                pos, delta = best_insertion(route, c)
                score = (delta, dist(depot, c), d, c)
                if best_score is None or score < best_score:
                    best_score = score
                    best_c = c
                    best_pos = pos
            if best_c is not None:
                route.insert(best_pos, best_c)
                unrouted.remove(best_c)
                load += demand(best_c)
                improved = True

        routes.append(route)

    repaired = []
    for route in routes:
        cur = []
        cur_load = 0
        for c in route:
            d = demand(c)
            if cur and cur_load + d > capacity:
                repaired.append(cur)
                cur = [c]
                cur_load = d
            else:
                cur.append(c)
                cur_load += d
        if cur:
            repaired.append(cur)
    routes = repaired

    def two_opt(route):
        n = len(route)
        if n < 4:
            return route[:]
        best = route[:]
        best_cost = route_cost(best)
        changed = True
        while changed:
            changed = False
            for i in range(n - 1):
                for k in range(i + 1, n):
                    cand = best[:i] + best[i:k + 1][::-1] + best[k + 1:]
                    cc = route_cost(cand)
                    if cc < best_cost - 1e-12 or (abs(cc - best_cost) <= 1e-12 and cand < best):
                        best = cand
                        best_cost = cc
                        changed = True
                        break
                if changed:
                    break
        return best

    def relocate_in_route(route):
        best = route[:]
        best_cost = route_cost(best)
        if len(best) < 2:
            return best
        changed = True
        while changed:
            changed = False
            n = len(best)
            for i in range(n):
                c = best[i]
                rest = best[:i] + best[i + 1:]
                for pos in range(len(rest) + 1):
                    cand = rest[:pos] + [c] + rest[pos:]
                    cc = route_cost(cand)
                    if cc < best_cost - 1e-12 or (abs(cc - best_cost) <= 1e-12 and cand < best):
                        best = cand
                        best_cost = cc
                        changed = True
                        break
                if changed:
                    break
        return best

    routes = [relocate_in_route(two_opt(r)) for r in routes]

    changed = True
    while changed:
        changed = False
        route_loads = [route_load(r) for r in routes]
        route_costs = [route_cost(r) for r in routes]
        order = list(range(len(routes)))
        order.sort(key=lambda idx: (-route_costs[idx], -len(routes[idx]), idx))

        for i in order:
            r1 = routes[i]
            if not r1:
                continue
            for j in range(len(routes)):
                if i == j:
                    continue
                r2 = routes[j]
                load2 = route_loads[j]
                for a in range(len(r1)):
                    c = r1[a]
                    d = demand(c)
                    if load2 + d > capacity:
                        continue
                    base1 = r1[:a] + r1[a + 1:]
                    for pos in range(len(r2) + 1):
                        cand2 = r2[:pos] + [c] + r2[pos:]
                        cand1 = base1
                        new_cost = route_cost(cand1) + route_cost(cand2)
                        old_cost = route_costs[i] + route_costs[j]
                        if new_cost < old_cost - 1e-12:
                            routes[i] = cand1
                            routes[j] = cand2
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            if changed:
                break

    routes = [r for r in routes if r]
    for r in routes:
        seq = r[:]
        if seq:
            ordered = [seq[0]]
            for c in seq[1:]:
                pos, _ = best_insertion(ordered, c)
                ordered.insert(pos, c)
            r[:] = ordered

    return routes
